FILES = {
 "RUN7_mk_run7.py": "\"\"\"RUN7 generator (Grok, green_regular_character lane). Reads upstream files fetched at pin\n40e56bab026552e089d7afcfeff08d2defb9c005 into /workspace/rh_green_up and writes GreenCompanion/Run7.lean.\nTextual operations only: proof bodies sliced verbatim; `open` lines re-pointed at GreenCompanion namespaces;\nin DerTail the two upstream dependency references are renamed to carrier-class fields (BZH.h, BlockParH.h)\nwhose types are the exact upstream statements (BZPart from RUN4 SumWhGG, BlockParPart from RUN6).\"\"\"\nU = \"/workspace/rh_green_up/src/Development/AbelianVarietyTheory/\"\nL = \"/workspace/rh_green_lean/GreenCompanion/\"\nCT = \"Proofs/CharacterTheory/\"; FM = \"Proofs/FlagMeasures/\"\ndef rd(p): return open(U + p, encoding=\"utf-8\").read()\ndef body(p, ns):\n    t = rd(p); key = \"namespace \" + ns + \"\\n\"\n    a = t.index(key) + len(key); b = t.rindex(\"end \" + ns)\n    return t[a:b].strip(\"\\n\") + \"\\n\"\ndef sub(t, pairs):\n    for x, y in pairs:\n        assert x in t, x\n        t = t.replace(x, y)\n    return t\nOPEN_UP = \"open Polynomial Formalism.MainNotions.ArithmeticCylinders GlobalTheory.GLq GlobalTheory.GLm\\n\"\nOPEN_GC = \"open Polynomial GreenCompanion.GLm\\n\"\nfca = body(CT + \"MonicFactorizationConvolutionFiniteCommAssocAdd.lean\", \"GlobalTheory.CuspGL\")\nvm1 = body(CT + \"AdditiveEqPolynomialVonMangoldtConvolutionOne.lean\", \"GlobalTheory.CuspGL\")\npar = body(FM + \"BlockParabolicUnitriangularSubgroupsGLnPrimeFiel.lean\", \"GlobalTheory.GLm.ParBasic\")\ntcl = sub(body(FM + \"IsMirabolicConjInvariantTwistedTailMeanFun.lean\", \"GlobalTheory.GLm.TailClass\"), [(OPEN_UP, OPEN_GC)])\ndtl = sub(body(FM + \"DerTail.lean\", \"GlobalTheory.GLm.DerTail\"), [\n    (\"variable {g : ℕ} [Fact g.Prime]\\n\", \"variable {g : ℕ} [Fact g.Prime]\\nvariable [hBZ : BZH] [hBP : BlockParH]\\ninclude hBZ hBP\\n\"),\n    (\"GlobalTheory.T.bernsteinZelevinskyDerivativeGLn_eq_twisted_sum\", \"BZH.h\"),\n    (\"GlobalTheory.T.blockParabolic_unitriangular_subgroups_GLnPrimeField\", \"BlockParH.h\")])\nassert \"GlobalTheory.\" not in fca + vm1 + par + tcl + dtl\nnames = [\"CuspGL.conv_basic\", \"CuspGL.mangoldt_conv_spec\", \"GLm.ParBasic.par_basic\", \"GLm.TailClass.isMirClass_tail\",\n         \"GLm.DerTail.der_tail\", \"finCommPart_holds\", \"vonMangoldtOnePart_holds\", \"logConvPart_holds\", \"massPart_of_leaves7\",\n         \"blockParPart_holds\", \"tailMirPart_holds\", \"derTailPart_of_BZ\", \"mirIndPart_holds\", \"mirConjPart_of_leaves7\",\n         \"mirPart_of_leaves7\", \"sumWhGGPart_of_leaves7\"]\nout = \"\"\"/-\nGreen lane RUN7 companion (Grok, 2026-11-24). Generated by RUN7_mk_run7.py from upstream\nleanprover-community/riemann-hypothesis @ 40e56bab026552e089d7afcfeff08d2defb9c005:\n  Proofs/CharacterTheory/MonicFactorizationConvolutionFiniteCommAssocAdd.lean  (CuspGL.conv_basic and helpers)\n  Proofs/CharacterTheory/AdditiveEqPolynomialVonMangoldtConvolutionOne.lean    (CuspGL.mangoldt_conv_spec and helpers)\n  Proofs/FlagMeasures/BlockParabolicUnitriangularSubgroupsGLnPrimeFiel.lean   (GLm.ParBasic.*)\n  Proofs/FlagMeasures/IsMirabolicConjInvariantTwistedTailMeanFun.lean          (GLm.TailClass.*)\n  Proofs/FlagMeasures/DerTail.lean                                             (GLm.DerTail.*)\nProof bodies verbatim; only the `open` lines are re-pointed at GreenCompanion namespaces. In DerTail the upstream\ndependencies T.bernsteinZelevinskyDerivativeGLn_eq_twisted_sum / T.blockParabolic_unitriangular_subgroups_GLnPrimeField\nare supplied as Prop-valued classes BZH / BlockParH whose field types are BZPart / BlockParPart (exact upstream\nstatement text, RUN4 / RUN6). Definitions come from earlier runs' modules. No sorry, no axiom.\n-/\nimport GreenCompanion.Run6\n\nnoncomputable section\nopen Polynomial\n\nnamespace GreenCompanion\n\n/-- carrier class for the hypothesis `BZPart` (= upstream `T.bernsteinZelevinskyDerivativeGLn_eq_twisted_sum`). -/\nclass BZH : Prop where\n  h : BZPart\n\nsection CuspPart\nopen CuspGL\nnamespace CuspGL\nsection FinComm\n\"\"\" + fca + \"\"\"end FinComm\nsection VonMangoldtOne\n\"\"\" + vm1 + \"\"\"end VonMangoldtOne\nend CuspGL\n\n/-- RUN6 leaf `T.monicFactorizationConvolution_finite_comm_assoc_add` (`FinCommPart`): closed. -/\ntheorem finCommPart_holds : FinCommPart := CuspGL.conv_basic\n/-- RUN6 leaf `T.additive_eq_polynomialVonMangoldt_convolution_one` (`VonMangoldtOnePart`): closed. -/\ntheorem vonMangoldtOnePart_holds : VonMangoldtOnePart := CuspGL.mangoldt_conv_spec\n/-- RUN4 leaf `LogConvPart` (= upstream `T.additive_mul_eq_vonMangoldt_convolution`): closed. -/\ntheorem logConvPart_holds : LogConvPart := logConvPart_of_deps finCommPart_holds vonMangoldtOnePart_holds\n/-- RUN3 `MassPart` (= upstream `T.endomorphismMass_mobiusInverse_monic_eq`) from the current leaves (RUN7). -/\ntheorem massPart_of_leaves7 (hConj : ConjPart) (hParMass : ParMassPart) (hPsiSum : PsiSumPart) : MassPartR3 :=\n  massPart_of_leaves6 hConj hParMass hPsiSum finCommPart_holds vonMangoldtOnePart_holds\nend CuspPart\n\nnamespace GLm.ParBasic\nopen Polynomial GreenCompanion.GLm\nopen scoped Classical\n\"\"\" + par + \"\"\"end GLm.ParBasic\n\nnamespace GLm.TailClass\n\"\"\" + tcl + \"\"\"end GLm.TailClass\n\nnamespace GLm.DerTail\nopen Polynomial GreenCompanion.GLm\nopen scoped Classical\n\"\"\" + dtl + \"\"\"end GLm.DerTail\n\n/-- RUN6 leaf `T.blockParabolic_unitriangular_subgroups_GLnPrimeField` (`BlockParPart`): closed. -/\ntheorem blockParPart_holds : BlockParPart := GLm.ParBasic.par_basic\n/-- RUN6 leaf `T.isMirabolicConjInvariant_twistedTailMeanFun` (`TailMirPart`): closed. -/\ntheorem tailMirPart_holds : TailMirPart := GLm.TailClass.isMirClass_tail\n/-- RUN6 leaf `T.der_tail_of_lt_of_le` (`DerTailPart`) from `BZPart` (BlockPar discharged). -/\ntheorem derTailPart_of_BZ (hBZp : BZPart) : DerTailPart := by\n  haveI : BZH := ⟨hBZp⟩\n  haveI : BlockParH := ⟨blockParPart_holds⟩\n  exact GLm.DerTail.der_tail\n/-- RUN5 leaf `MirIndPart`: closed. -/\ntheorem mirIndPart_holds : MirIndPart := mirIndPart_of_deps blockParPart_holds\n/-- RUN5 leaf `MirConjPart` from the remaining leaves. -/\ntheorem mirConjPart_of_leaves7 (hMT : MirTailPart) (hPP : PhiPlusPart) (hBZp : BZPart) : MirConjPart :=\n  mirConjPart_of_deps tailMirPart_holds hMT hPP (derTailPart_of_BZ hBZp)\n/-- RUN4 leaf `MirPart` from the remaining leaves. -/\ntheorem mirPart_of_leaves7 (hMT : MirTailPart) (hPP : PhiPlusPart) (hBZp : BZPart) : MirPart :=\n  mirPart_of_leaves6 tailMirPart_holds hMT hPP (derTailPart_of_BZ hBZp) blockParPart_holds\n/-- RUN3 `SumWhGGPart` (= upstream `GLm.GGSum.sum_wh_gg`) from the remaining leaves (RUN7). -/\ntheorem sumWhGGPart_of_leaves7 (hWJ : WJPart) (hWhMul : WhMulPart) (hBZp : BZPart) (hMT : MirTailPart)\n    (hPP : PhiPlusPart) : SumWhGGPart :=\n  sumWhGGPart_of_leaves6' hWJ hWhMul hBZp tailMirPart_holds hMT hPP (derTailPart_of_BZ hBZp) blockParPart_holds\n\nend GreenCompanion\n\n\"\"\" + \"\".join(\"#print axioms GreenCompanion.\" + n + \"\\n\" for n in names)\nopen(L + \"Run7.lean\", \"w\", encoding=\"utf-8\").write(out)\nprint(\"written\", out.count(\"\\n\"), \"lines\")\n",
 "RUN7_green_exact_checks.py": "\"\"\"RUN7 exact finite checks (Grok). Exact integer arithmetic mod a prime g; brute force over all n x n matrices.\n(H) BlockPar: for n = a + b, the block-parabolic set {x in GL_n(F_g) : x_ij = 0 for j < a <= i} is closed under\n    product and inverse; tl/br blocks of members are invertible and multiplicative; each fibre over (h1,h2) has\n    exactly g^(a*b) elements; total = |GL_a| |GL_b| g^(a*b). Upper-unitriangular set closed under product/inverse.\nNegative control: the fibre count with g^(a*b+1) must FAIL.\"\"\"\nimport itertools\ndef mul(A, B, g):\n    n = len(A); return tuple(tuple(sum(A[i][k]*B[k][j] for k in range(n)) % g for j in range(n)) for i in range(n))\ndef det(A, g):\n    n = len(A); M = [list(r) for r in A]; d = 1\n    for c in range(n):\n        p = next((r for r in range(c, n) if M[r][c] % g), None)\n        if p is None: return 0\n        if p != c: M[c], M[p] = M[p], M[c]; d = -d\n        d = d * M[c][c] % g; inv = pow(M[c][c], g-2, g)\n        for r in range(c+1, n):\n            f = M[r][c]*inv % g\n            M[r] = [(M[r][k]-f*M[c][k]) % g for k in range(n)]\n    return d % g\ndef GL(n, g):\n    out = []\n    for e in itertools.product(range(g), repeat=n*n):\n        A = tuple(tuple(e[i*n:(i+1)*n]) for i in range(n))\n        if det(A, g): out.append(A)\n    return out\ndef blk(A, lo, hi): return tuple(tuple(A[i][j] for j in range(lo, hi)) for i in range(lo, hi))\nmism = 0; neg = 0\nfor g, n in [(2, 2), (2, 3), (3, 2)]:\n    G = GL(n, g); I = tuple(tuple(int(i == j) for j in range(n)) for i in range(n))\n    inv = {}\n    for A in G:\n        for B in G:\n            if mul(A, B, g) == I: inv[A] = B; break\n    U = [A for A in G if all(A[i][i] == 1 for i in range(n)) and all(A[i][j] == 0 for i in range(n) for j in range(i))]\n    Us = set(U); okU = all(mul(x, y, g) in Us for x in U for y in U) and all(inv[x] in Us for x in U)\n    mism += (not okU)\n    for a in range(n + 1):\n        b = n - a\n        P = [A for A in G if all(A[i][j] == 0 for i in range(n) for j in range(n) if j < a <= i)]\n        Ps = set(P)\n        closed = all(mul(x, y, g) in Ps for x in P for y in P) and all(inv[x] in Ps for x in P)\n        units = all(det(blk(x, 0, a), g) and det(blk(x, a, n), g) for x in P) if True else True\n        multi = all(blk(mul(x, y, g), 0, a) == mul(blk(x, 0, a), blk(y, 0, a), g) and\n                    blk(mul(x, y, g), a, n) == mul(blk(x, a, n), blk(y, a, n), g) for x in P for y in P)\n        fib = {}\n        for x in P: fib[(blk(x, 0, a), blk(x, a, n))] = fib.get((blk(x, 0, a), blk(x, a, n)), 0) + 1\n        ga, gb = len(GL(a, g)) if a else 1, len(GL(b, g)) if b else 1\n        fibok = len(fib) == ga * gb and all(v == g ** (a * b) for v in fib.values())\n        tot = len(P) == ga * gb * g ** (a * b)\n        negfail = not all(v == g ** (a * b + 1) for v in fib.values())\n        ok = closed and units and multi and fibok and tot\n        mism += (not ok); neg += negfail\n        print(f\"g={g} n={n} a={a} b={b}: |P|={len(P)} = {ga}*{gb}*{g}^{a*b} closed={closed} units={units} mult={multi} fibres={fibok} U-closed={okU} {'ok' if ok else 'MISMATCH'}\")\nprint(\"(H) mismatches:\", mism, \"| negative control failed as expected in\", neg, \"cases\")\n",
 "RUN7_build_all.sh": "#!/bin/bash\n# RUN7 (a): rebuild every Green companion module, one module (one lake invocation) at a time, with nice.\ncd /workspace/rh_green_lean\nexport OMP_NUM_THREADS=1\nfor m in Exhaustion Bridge LabelDefs GenericCount MackeyCusp RootSumCore CuspGLDefs ParabVirt IpglRootSum CuspGLRun3 GGNorm CuspGLRun4 SumWhGG Run5 Run6 LeavesIPN; do\n  s=$(date +%s)\n  nice -n 10 lake build GreenCompanion.$m > /workspace/rh_green_work/run7/logs/$m.log 2>&1\n  rc=$?\n  echo \"$m exit=$rc secs=$(( $(date +%s) - s ))\" >> /workspace/rh_green_work/run7/logs/SUMMARY.txt\ndone\necho DONE >> /workspace/rh_green_work/run7/logs/SUMMARY.txt\n",
 "RUN7_closure.py": "\"\"\"Transitive project-import closure of the upstream Green proof module (Grok RUN7). Usage: closure.py SRC_ROOT\nParses `import X` lines recursively; modules whose file is absent under SRC_ROOT are external (Mathlib etc.).\"\"\"\nimport os, re, sys\nsrc = sys.argv[1]\nroot = \"Development.AbelianVarietyTheory.Proofs.InertiaEigenvalues.GreenCuspidalCharsByRegularCharsProof\"\nseen = set(); stack = [root]; ext = set(); nbytes = nlines = 0\nwhile stack:\n    m = stack.pop()\n    if m in seen: continue\n    p = os.path.join(src, m.replace(\".\", \"/\") + \".lean\")\n    if not os.path.exists(p): ext.add(m.split(\".\")[0]); continue\n    seen.add(m); t = open(p, encoding=\"utf-8\").read(); nbytes += len(t.encode()); nlines += t.count(\"\\n\")\n    for l in t.splitlines():\n        mm = re.match(r\"import\\s+(\\S+)\", l)\n        if mm: stack.append(mm.group(1))\nprint(\"project modules in closure:\", len(seen), \"lines:\", nlines, \"bytes:\", nbytes, \"external roots:\", sorted(ext))\n",
 "RUN7_run_pinned_env.sh": "#!/usr/bin/env bash\n# Elaborate $1 against the published pinned upstream environment (read-only): upstream lake-manifest package oleans in\n# /workspace/rh_orig/.lake/packages + the frozen-mirror upstream oleans symlink farm /workspace/rh_full_build (lean_validation\n# lane). Upstream lakefile [leanOptions]. No -o: no .olean written. (Same invocation as LEAVES_I_PN_run_pinned_env.sh.)\nR=/workspace/rh_orig/.lake/packages\nexport LEAN_PATH=$R/Cli/.lake/build/lib/lean:$R/batteries/.lake/build/lib/lean:$R/Qq/.lake/build/lib/lean:$R/aesop/.lake/build/lib/lean:$R/proofwidgets/.lake/build/lib/lean:$R/importGraph/.lake/build/lib/lean:$R/LeanSearchClient/.lake/build/lib/lean:$R/plausible/.lake/build/lib/lean:$R/mathlib/.lake/build/lib/lean:/workspace/rh_full_build/lib/lean:$HOME/.elan/toolchains/leanprover--lean4---v4.33.1/lib/lean\nexport LEAN_ABORT_ON_PANIC=1 OMP_NUM_THREADS=1\nstart=$(date +%s)\necho \"+ lean [upstream leanOptions] $1  ($(date -Is))\"\nnice -n 10 $HOME/.elan/toolchains/leanprover--lean4---v4.33.1/bin/lean -DautoImplicit=false -DrelaxedAutoImplicit=false -DmaxSynthPendingDepth=3 -Dpp.unicode.fun=true -DmaxHeartbeats=4000000 --tstack=400000 \"$1\"\necho \"EXIT=$? elapsed=$(( $(date +%s)-start ))s\"\n",
 "RUN7_ImportedAxioms.lean": "import Development.AbelianVarietyTheory.Proofs.InertiaEigenvalues.GreenCuspidalCharsByRegularCharsProof\n#print axioms GlobalTheory.greenRegularCharacters_holds\n",
 "RUN7_GreenProofAxioms.note": "GreenProofAxioms.lean = upstream GreenCuspidalCharsByRegularCharsProof.lean at the pin (blob 8b77636fe17dd07c59e7b76bc1234be319b82395) byte-for-byte, followed by:\n\n#print axioms GlobalTheory.greenRegularCharacters_holds\n",
 "RUN7_lakefile.diff": "--- /workspace/rh_green_work/lakefile.before.toml\t2026-11-24 10:36:33.701647088 +0000\n+++ /workspace/rh_green_lean/lakefile.toml\t2026-11-24 10:36:33.713646975 +0000\n@@ -1,5 +1,13 @@\n name = \"GreenCompanion\"\n defaultTargets = [\"GreenCompanion\"]\n+moreLeanArgs = [\"--tstack=400000\"]\n+\n+[leanOptions]\n+autoImplicit = false\n+relaxedAutoImplicit = false\n+maxSynthPendingDepth = 3\n+pp.unicode.fun = true\n+maxHeartbeats = 4000000\n \n [[require]]\n name = \"mathlib\"\n"
}
